window.CIVIL_SET_DATA = window.CIVIL_SET_DATA || {};
window.CIVIL_SET_DATA["past-06"] = {"title":"Past Paper Set 6","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-06-001","src":"PAST-06-001","text":"What is the purpose of providing waterproof tiles?","options":[{"key":"a","text":"Help to reduce fire catch"},{"key":"b","text":"Provide smooth surface"},{"key":"c","text":"Help in sound insulation"},{"key":"d","text":"Prevents water from entering"}],"answer":"d","explanation":"Waterproof (vitrified or glazed) tiles act as a barrier against water, keeping moisture from seeping into the floor, wall or roof below.","marks":1,"source":{"kind":"past","set":6,"question":1,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q1 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-06-019","src":"PAST-06-019","text":"Grout is a mixture of","options":[{"key":"a","text":"Water and cement"},{"key":"b","text":"Water, cement and sand"},{"key":"c","text":"Water, cement and lime"},{"key":"d","text":"Water, lime and sand"}],"answer":"b","explanation":"Grout is a fluid mix of cement, fine sand and water, poured or injected to fill joints, voids and cracks. Neat cement grout (cement and water) is also used for fine cracks.","marks":1,"source":{"kind":"past","set":6,"question":19,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q19 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-06-024","src":"PAST-06-024","text":"Which of the following is the primary raw material in cement manufacturing?","options":[{"key":"a","text":"Mica"},{"key":"b","text":"Limestone"},{"key":"c","text":"Aluminium"},{"key":"d","text":"Coal"}],"answer":"b","explanation":"Portland cement is made by burning a mix of calcareous material (limestone) and argillaceous material (clay or shale) to clinker. Limestone supplies the lime (CaO).","marks":1,"source":{"kind":"past","set":6,"question":24,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q24 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-06-027","src":"PAST-06-027","text":"The moment of inertia of a rectangle about its CG with the axis parallel to the X-axis is","options":[{"key":"a","text":"bd<sup>3</sup>/12"},{"key":"b","text":"db<sup>3</sup>/12"},{"key":"c","text":"bd<sup>3</sup>/3"},{"key":"d","text":"db<sup>3</sup>/3"}],"answer":"a","explanation":"About the horizontal centroidal axis of a \\(b \\times d\\) rectangle, \\[I = \\dfrac{bd^3}{12}\\] About the base it is \\(\\dfrac{bd^3}{3}\\).","marks":1,"source":{"kind":"past","set":6,"question":27,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q27 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-06-056","src":"PAST-06-056","text":"What is used for a rainwater gutter on a roof?","options":[{"key":"a","text":"Cement"},{"key":"b","text":"Sand"},{"key":"c","text":"Bitumen"},{"key":"d","text":"Steel sheet"}],"answer":"d","explanation":"Roof gutters are formed from galvanised steel (or other metal) sheets, which are light, watertight and easy to shape and fix.","marks":1,"source":{"kind":"past","set":6,"question":56,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q56 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-06-061","src":"PAST-06-061","text":"If an irrigation channel has a side slope of 1:S, bed width B, depth y and length L, then the total area of the side slopes is","options":[{"key":"a","text":"2Ly√(1+s<sup>2</sup>)"},{"key":"b","text":"2LB√(1+s<sup>2</sup>)"},{"key":"c","text":"Ly√(1+s<sup>2</sup>)"},{"key":"d","text":"LB√(1+s<sup>2</sup>)"}],"answer":"a","explanation":"Each sloping side has an inclined length \\(y\\sqrt{1 + s^2}\\), so the two sides over length \\(L\\) cover \\[A = 2Ly\\sqrt{1 + s^2}\\] (used for lining quantities).","marks":2,"source":{"kind":"past","set":6,"question":61,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q61 · 2 marks"},"topic":"ACiE0106"},{"id":"PAST-06-078","src":"PAST-06-078","text":"What is the direction of the closing error?","options":[{"key":"a","text":"tan δ = ΣL/ΣD"},{"key":"b","text":"tan δ = ΣL<sup>2</sup>/ΣD<sup>2</sup>"},{"key":"c","text":"tan δ = ΣD/ΣL"},{"key":"d","text":"tan δ = ΣD<sup>2</sup>/ΣL<sup>2</sup>"}],"answer":"c","explanation":"The closing error \\[e = \\sqrt{(\\Sigma L)^2 + (\\Sigma D)^2}\\] has its bearing given by \\[\\tan\\delta = \\dfrac{\\Sigma D}{\\Sigma L}\\] (departure error over latitude error).","marks":2,"source":{"kind":"past","set":6,"question":78,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q78 · 2 marks"},"topic":"ACiE0105"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-06-007","src":"PAST-06-007","text":"What is the meaning of SC in soil classification?","options":[{"key":"a","text":"Soil with plastic fines"},{"key":"b","text":"Sand with plastic fines"},{"key":"c","text":"Sand with inorganic fines"},{"key":"d","text":"Sand with common fines"}],"answer":"b","explanation":"In the Unified system the first letter is the major fraction (S for sand) and the second describes the fines. C means clayey (plastic) fines, so SC is clayey sand, i.e. sand with plastic fines.","marks":1,"source":{"kind":"past","set":6,"question":7,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q7 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-06-008","src":"PAST-06-008","text":"The formula for the area ratio of a sampler is","options":[{"key":"a","text":"(D<sub>1</sub><sup>2</sup> − D<sub>2</sub><sup>2</sup>)/D<sub>1</sub><sup>2</sup> × 100"},{"key":"b","text":"(D<sub>2</sub><sup>2</sup> − D<sub>1</sub><sup>2</sup>)/D<sub>1</sub><sup>2</sup> × 100"},{"key":"c","text":"(D<sub>2</sub><sup>2</sup> − D<sub>1</sub><sup>2</sup>)/D<sub>2</sub><sup>2</sup> × 100"},{"key":"d","text":"(D<sub>1</sub><sup>2</sup> − D<sub>2</sub><sup>2</sup>)/D<sub>2</sub><sup>2</sup> × 100"}],"answer":"b","explanation":"The area ratio is \\[A_r = \\dfrac{D_2^2 - D_1^2}{D_1^2} \\times 100\\] where \\(D_2\\) is the outer and \\(D_1\\) the inner diameter of the cutting edge. It should be below 10-20% for undisturbed samples. The source key prints (a), but its own formula is option (b).","marks":1,"source":{"kind":"past","set":6,"question":8,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q8 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-06-010","src":"PAST-06-010","text":"C<sub>m</sub> is also called","options":[{"key":"a","text":"Cohesion value of soil"},{"key":"b","text":"Applied shear stress"},{"key":"c","text":"Direct stress on soil"},{"key":"d","text":"Shear strength of soil"}],"answer":"b","explanation":"The mobilised cohesion is \\[C_m = \\dfrac{c}{F_c}\\] It is the part of the cohesion actually developed to balance the applied shear stress on the slip surface, not the full cohesion.","marks":1,"source":{"kind":"past","set":6,"question":10,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q10 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-06-011","src":"PAST-06-011","text":"The active earth pressure of a soil is defined as the lateral pressure exerted by soil","options":[{"key":"a","text":"when it is at rest"},{"key":"b","text":"when the retaining wall has no movement relative to the back fill"},{"key":"c","text":"when the retaining wall tends to move away from the back fill"},{"key":"d","text":"when the retaining wall moves into the soil"}],"answer":"c","explanation":"Active pressure develops when the wall yields away from the backfill and the soil reaches its lower limiting (active) state. Movement into the soil gives passive pressure, and no movement gives earth pressure at rest.","marks":1,"source":{"kind":"past","set":6,"question":11,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q11 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-06-012","src":"PAST-06-012","text":"A mat foundation is provided when","options":[{"key":"a","text":"heavy load has to be transferred"},{"key":"b","text":"isolated footings cover more than 50% area"},{"key":"c","text":"the soil is weak"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"A raft is chosen when column loads are heavy, when the soil is weak (low bearing capacity or erratic), or when individual footings would cover more than about half the plan area.","marks":1,"source":{"kind":"past","set":6,"question":12,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q12 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-06-013","src":"PAST-06-013","text":"Which of the following is not an assumption of Terzaghi's bearing capacity theory?","options":[{"key":"a","text":"Base of the footing is smooth"},{"key":"b","text":"Depth of foundation is less than or equal to its width"},{"key":"c","text":"Load applied is vertical and non-eccentric"},{"key":"d","text":"Soil is isotropic and homogeneous"}],"answer":"a","explanation":"Terzaghi assumed a rough footing base, so the soil wedge beneath it moves with the footing. He also assumed a shallow strip footing (D<sub>f</sub> ≤ B), a vertical concentric load and homogeneous isotropic soil.","marks":1,"source":{"kind":"past","set":6,"question":13,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q13 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-06-079","src":"PAST-06-079","text":"Find the porosity if the specific gravity is 2.6 and the water content is 45% for a fully saturated condition of soil.","options":[{"key":"a","text":"0.5"},{"key":"b","text":"0.55"},{"key":"c","text":"0.6"},{"key":"d","text":"0.65"}],"answer":"b","explanation":"For a saturated soil \\[e = wG = 0.45 \\times 2.6 = 1.17\\] so \\[\\begin{aligned} n &amp;= \\dfrac{e}{1 + e} = \\dfrac{1.17}{2.17} \\\\ &amp;\\approx 0.54 \\approx 0.55 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":6,"question":79,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q79 · 2 marks"},"topic":"ACiE0201"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-06-003","src":"PAST-06-003","text":"When condensation takes place below freezing point, it is known as","options":[{"key":"a","text":"Frost"},{"key":"b","text":"Mist"},{"key":"c","text":"Haze"},{"key":"d","text":"Fog"}],"answer":"a","explanation":"When the dew point is below 0°C, water vapour deposits directly as ice crystals on cold surfaces, forming frost.","marks":1,"source":{"kind":"past","set":6,"question":3,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q3 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-06-016","src":"PAST-06-016","text":"EGL − HGL gives","options":[{"key":"a","text":"Pressure head"},{"key":"b","text":"Potential energy"},{"key":"c","text":"Velocity head"},{"key":"d","text":"Energy slope"}],"answer":"c","explanation":"The energy grade line lies above the hydraulic grade line by \\[\\text{EGL} - \\text{HGL} = \\dfrac{V^2}{2g}\\] so their difference is the velocity head.","marks":1,"source":{"kind":"past","set":6,"question":16,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q16 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-06-032","src":"PAST-06-032","text":"The coefficient of friction for laminar flow is","options":[{"key":"a","text":"16/Re"},{"key":"b","text":"24/Re"},{"key":"c","text":"32/Re"},{"key":"d","text":"64/Re"}],"answer":"a","explanation":"For laminar pipe flow the Darcy friction factor is \\[f = \\dfrac{64}{Re}\\] The coefficient of friction (Fanning, \\(f' = \\dfrac{f}{4}\\)) is \\(\\dfrac{16}{Re}\\).","marks":1,"source":{"kind":"past","set":6,"question":32,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q32 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-06-033","src":"PAST-06-033","text":"What are the sediments that are rolling, sliding and bouncing called?","options":[{"key":"a","text":"Bed load"},{"key":"b","text":"Suspended load"},{"key":"c","text":"Dissolved load"},{"key":"d","text":"Contact load"}],"answer":"a","explanation":"Bed load moves along the bed by rolling, sliding and saltation (bouncing). Suspended load is carried within the flow by turbulence.","marks":1,"source":{"kind":"past","set":6,"question":33,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q33 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-06-037","src":"PAST-06-037","text":"Which of the following expressions is correct?","options":[{"key":"a","text":"GM = I/V − BG"},{"key":"b","text":"BG = I/V − GM"},{"key":"c","text":"I/V = GM − BG"},{"key":"d","text":"BG = I/V"}],"answer":"a","explanation":"The metacentric height is \\[GM = BM - BG\\] \\[BM = \\dfrac{I}{V}\\] where \\(I\\) is the second moment of the waterline area and \\(V\\) is the displaced volume.","marks":1,"source":{"kind":"past","set":6,"question":37,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q37 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-06-055","src":"PAST-06-055","text":"With an increase in temperature, the viscosity (of a liquid)","options":[{"key":"a","text":"Increases"},{"key":"b","text":"Decreases"},{"key":"c","text":"Remains same"},{"key":"d","text":"Can not be said"}],"answer":"b","explanation":"In liquids, viscosity comes from cohesion, which weakens as temperature rises, so viscosity decreases. In gases, viscosity increases with temperature.","marks":1,"source":{"kind":"past","set":6,"question":55,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q55 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-06-067","src":"PAST-06-067","text":"If the dew point is above 0°C, then","options":[{"key":"a","text":"Frost will form"},{"key":"b","text":"Vapour will form"},{"key":"c","text":"Dew will form"},{"key":"d","text":"Hailstone will form"}],"answer":"c","explanation":"When air cools to a dew point above freezing, the vapour condenses as liquid dew. A dew point below 0°C gives frost.","marks":2,"source":{"kind":"past","set":6,"question":67,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q67 · 2 marks"},"topic":"ACiE0306"},{"id":"PAST-06-074","src":"PAST-06-074","text":"A jar is placed 1 m above the floor and a tap with cross-sectional area 0.1 m<sup>2</sup> at the bottom of the jar is opened. The water jet discharges 0.02 m<sup>3</sup>/s of water and hits the floor at 1.8 m distance. If the height of the jar is 1 m and it is fully filled, what would be the coefficient of velocity?","options":[{"key":"a","text":"0.80"},{"key":"b","text":"0.85"},{"key":"c","text":"0.90"},{"key":"d","text":"0.95"}],"answer":"c","explanation":"With the jet falling \\(y = 1\\) m under a head \\(H = 1\\) m, \\[\\begin{aligned} C_v &amp;= \\dfrac{x}{2\\sqrt{yH}} = \\dfrac{1.8}{2\\sqrt{1 \\times 1}} \\\\ &amp;= 0.90 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":6,"question":74,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q74 · 2 marks"},"topic":"ACiE0303"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-06-026","src":"PAST-06-026","text":"The stiffness matrix method is also called","options":[{"key":"a","text":"Flexibility method"},{"key":"b","text":"Force method"},{"key":"c","text":"Displacement method"},{"key":"d","text":"All of the above"}],"answer":"c","explanation":"The stiffness method takes joint displacements as unknowns and solves [K]{Δ} = {P}, so it is a displacement method. The flexibility method is a force method.","marks":1,"source":{"kind":"past","set":6,"question":26,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q26 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-06-028","src":"PAST-06-028","text":"The load beyond which a body will have a permanent set is","options":[{"key":"a","text":"Rigidity"},{"key":"b","text":"Proof resilience"},{"key":"c","text":"Proof load"},{"key":"d","text":"Proof stress"}],"answer":"c","explanation":"The proof load is the largest load a body can carry without permanent deformation, i.e. the load at the elastic limit. The strain energy stored at that load is the proof resilience.","marks":1,"source":{"kind":"past","set":6,"question":28,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q28 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-06-029","src":"PAST-06-029","text":"The influence line diagram for bending moment in a simply supported beam is a","options":[{"key":"a","text":"Straight line"},{"key":"b","text":"Parabola"},{"key":"c","text":"Triangle"},{"key":"d","text":"None of these"}],"answer":"c","explanation":"The ILD for moment at a section distant a from one support is a triangle with its peak ordinate a(L−a)/L under the section.","marks":1,"source":{"kind":"past","set":6,"question":29,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q29 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-06-030","src":"PAST-06-030","text":"What will be the deflection of a cantilever beam subjected to a point load W at its free end?","options":[{"key":"a","text":"WL<sup>3</sup>/3EI"},{"key":"b","text":"WL<sup>3</sup>/4EI"},{"key":"c","text":"WL<sup>3</sup>/6EI"},{"key":"d","text":"WL<sup>3</sup>/2EI"}],"answer":"a","explanation":"For a cantilever with a tip load, \\[\\delta = \\dfrac{WL^3}{3EI}, \\qquad \\theta = \\dfrac{WL^2}{2EI}\\]","marks":1,"source":{"kind":"past","set":6,"question":30,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q30 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-06-031","src":"PAST-06-031","text":"A moment M is acting at the free end of a cantilever beam. What will be the maximum moment developed in the beam?","options":[{"key":"a","text":"2M"},{"key":"b","text":"M"},{"key":"c","text":"M/2"},{"key":"d","text":"M/4"}],"answer":"b","explanation":"An end couple produces a constant bending moment M throughout the cantilever, with zero shear.","marks":1,"source":{"kind":"past","set":6,"question":31,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q31 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-06-060","src":"PAST-06-060","text":"A positive (sagging) bending moment causes …… members.","options":[{"key":"a","text":"Convex downward"},{"key":"b","text":"Concave downward"},{"key":"c","text":"Plano convex"},{"key":"d","text":"Plano concave"}],"answer":"a","explanation":"A sagging (positive) moment bends the beam concave upwards, i.e. convex downwards, with compression at the top and tension at the bottom.","marks":1,"source":{"kind":"past","set":6,"question":60,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q60 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-06-063","src":"PAST-06-063","text":"The maximum bending moment in a three hinged arch under a point load occurs on either side of its crown at","options":[{"key":"a","text":"h/4"},{"key":"b","text":"L/4"},{"key":"c","text":"L/(2√3)"},{"key":"d","text":"L/(3√2)"}],"answer":"c","explanation":"For a three-hinged parabolic arch with a rolling point load, the absolute maximum positive moment occurs with the load at \\(0.211L\\) from a support. That point is \\[\\dfrac{L}{2\\sqrt{3}}\\] from the crown on either side.","marks":2,"source":{"kind":"past","set":6,"question":63,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q63 · 2 marks"},"topic":"ACiE0405"},{"id":"PAST-06-071","src":"PAST-06-071","text":"After reaching the yield point, the strain in a test sample …… than stress.","options":[{"key":"a","text":"Increases heavily"},{"key":"b","text":"Increases slowly"},{"key":"c","text":"Decreases heavily"},{"key":"d","text":"Decreases slowly"}],"answer":"a","explanation":"Beyond yield, mild steel flows plastically: the strain grows greatly with little or no increase in stress (yield plateau, then strain hardening).","marks":2,"source":{"kind":"past","set":6,"question":71,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q71 · 2 marks"},"topic":"ACiE0402"},{"id":"PAST-06-072","src":"PAST-06-072","text":"A rod of area 1000 mm<sup>2</sup> has an axial pull of 2 kN. What is the shear stress on a plane inclined at 30° to the horizontal axis?","options":[{"key":"a","text":"2 N/mm<sup>2</sup>"},{"key":"b","text":"0.866 N/mm<sup>2</sup>"},{"key":"c","text":"0.667 N/mm<sup>2</sup>"},{"key":"d","text":"1 N/mm<sup>2</sup>"}],"answer":"b","explanation":"The axial stress is \\(\\sigma = \\dfrac{2000}{1000} = 2\\) N per mm<sup>2</sup>. On an oblique plane, \\[\\begin{aligned} \\tau &amp;= \\dfrac{\\sigma}{2}\\sin 2\\theta = 1 \\times \\sin 60^\\circ \\\\ &amp;= 0.866 \\end{aligned}\\] N per mm<sup>2</sup> (the same for \\(30^\\circ\\) or \\(60^\\circ\\)).","marks":2,"source":{"kind":"past","set":6,"question":72,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q72 · 2 marks"},"topic":"ACiE0402"}]},{"name":"Design of Structures","questions":[{"id":"PAST-06-002","src":"PAST-06-002","text":"Which steel section is commonly used for columns?","options":[{"key":"a","text":"ISMB"},{"key":"b","text":"ISLB"},{"key":"c","text":"ISWB"},{"key":"d","text":"ISSC"}],"answer":"d","explanation":"ISSC (Indian Standard special column) and ISHB sections have wide flanges, giving similar stiffness about both axes, which suits columns. ISMB, ISLB and ISWB are beam sections.","marks":1,"source":{"kind":"past","set":6,"question":2,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q2 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-06-020","src":"PAST-06-020","text":"Loss of prestress results in","options":[{"key":"a","text":"Decrease in compressive strength"},{"key":"b","text":"Decrease in tensile strength"},{"key":"c","text":"Decrease in shear strength"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"Losses (elastic shortening, shrinkage, creep, relaxation, friction, anchorage slip) reduce the effective precompression. The member then cracks at lower loads and loses part of its flexural, shear and compressive reserve.","marks":1,"source":{"kind":"past","set":6,"question":20,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q20 · 1 mark"},"topic":"ACiE0504"},{"id":"PAST-06-021","src":"PAST-06-021","text":"Permissible stress in steel is taken as","options":[{"key":"a","text":"Yield stress"},{"key":"b","text":"Ultimate stress"},{"key":"c","text":"Working stress"},{"key":"d","text":"None of the above"}],"answer":"c","explanation":"In working stress design, the permissible (working) stress is the yield stress divided by a factor of safety, and actual service stresses must not exceed it.","marks":1,"source":{"kind":"past","set":6,"question":21,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q21 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-06-022","src":"PAST-06-022","text":"The section in which the area of tensile steel is such that at the ultimate limit state the ultimate compressive strain in concrete is reached, while the tensile strain in the reinforcing steel is less than the yield strain, is known as","options":[{"key":"a","text":"Ultra reinforced section"},{"key":"b","text":"Over reinforced section"},{"key":"c","text":"Under reinforced section"},{"key":"d","text":"Balanced section"}],"answer":"b","explanation":"When the steel has not yielded as the concrete crushes (x<sub>u</sub> > x<sub>u,max</sub>), the section is over-reinforced and fails suddenly in compression. Under-reinforced sections yield first, and balanced sections reach both limits together.","marks":1,"source":{"kind":"past","set":6,"question":22,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q22 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-06-023","src":"PAST-06-023","text":"Which test is used to measure weathering of aggregate?","options":[{"key":"a","text":"Impact test"},{"key":"b","text":"Crushing test"},{"key":"c","text":"Soundness test"},{"key":"d","text":"Solubility test"}],"answer":"c","explanation":"The soundness test (repeated immersion in sodium or magnesium sulphate and drying) measures the resistance of aggregate to weathering. Impact and crushing tests measure toughness and strength.","marks":1,"source":{"kind":"past","set":6,"question":23,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q23 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-06-025","src":"PAST-06-025","text":"How many wind zones are there in Nepal?","options":[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"3"},{"key":"d","text":"4"}],"answer":"b","explanation":"NBC 104 divides Nepal into two wind zones: areas below about 3000 m (basic wind speed 47 m/s) and areas above 3000 m (55 m/s).","marks":1,"source":{"kind":"past","set":6,"question":25,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q25 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-06-042","src":"PAST-06-042","text":"Spot welding is used when two plates are placed","options":[{"key":"a","text":"one below the other"},{"key":"b","text":"one butting against the other"},{"key":"c","text":"one next to the other"},{"key":"d","text":"at right angles to each other"}],"answer":"a","explanation":"Spot (resistance) welding joins overlapping sheets: the plates are lapped one over the other and fused at spots between electrodes.","marks":1,"source":{"kind":"past","set":6,"question":42,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q42 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-06-059","src":"PAST-06-059","text":"The cracking of concrete (cement) occurs first in","options":[{"key":"a","text":"Singly reinforced"},{"key":"b","text":"Doubly reinforced"},{"key":"c","text":"Balanced"},{"key":"d","text":"All"}],"answer":"d","explanation":"In every reinforced section, the concrete on the tension face cracks once its low tensile strength is exceeded, well before failure. Cracking is therefore common to all these section types.","marks":1,"source":{"kind":"past","set":6,"question":59,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q59 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-06-075","src":"PAST-06-075","text":"The increase in permissible stress in the design of a wall subjected to eccentric load with eccentricity ratio &gt; 1/24 is","options":[{"key":"a","text":"10%"},{"key":"b","text":"20%"},{"key":"c","text":"25%"},{"key":"d","text":"33.33%"}],"answer":"c","explanation":"IS 1905 allows the permissible compressive stress to be raised by 25% when the eccentricity ratio exceeds \\(\\dfrac{1}{24}\\), because the peak stress then acts only at the edge.","marks":2,"source":{"kind":"past","set":6,"question":75,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q75 · 2 marks"},"topic":"ACiE0506"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-06-017","src":"PAST-06-017","text":"The thickness of filter media of a slow sand filter is","options":[{"key":"a","text":"90 to 110 cm"},{"key":"b","text":"80 to 90 cm"},{"key":"c","text":"70 to 80 cm"},{"key":"d","text":"60 to 80 cm"}],"answer":"a","explanation":"A slow sand filter has about 90–110 cm of fine sand over about 30–75 cm of graded gravel.","marks":1,"source":{"kind":"past","set":6,"question":17,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q17 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-06-018","src":"PAST-06-018","text":"Trachoma can be avoided by","options":[{"key":"a","text":"Increasing water supply"},{"key":"b","text":"Providing clean water"},{"key":"c","text":"Adding chlorine to water"},{"key":"d","text":"Not providing excess water"}],"answer":"a","explanation":"Trachoma is a water-washed disease spread by poor face and hand hygiene. It is controlled mainly by increasing the quantity of water available for washing, not by improving its quality. The source key gives (b).","marks":1,"source":{"kind":"past","set":6,"question":18,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q18 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-06-038","src":"PAST-06-038","text":"What is the detention time for a septic tank?","options":[{"key":"a","text":"Less than 12 hours"},{"key":"b","text":"12 hours"},{"key":"c","text":"24 hours"},{"key":"d","text":"48 hours"}],"answer":"c","explanation":"Septic tanks are designed for a detention time of about 24 hours (range 12–36 h) so that solids settle and are partly digested.","marks":1,"source":{"kind":"past","set":6,"question":38,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q38 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-06-039","src":"PAST-06-039","text":"Which pipe is strong in resisting internal stress but weak when stressed from outside?","options":[{"key":"a","text":"Cast iron"},{"key":"b","text":"Steel"},{"key":"c","text":"Ductile iron"},{"key":"d","text":"Concrete"}],"answer":"b","explanation":"Thin steel pipes resist high internal pressure well but can buckle or collapse under external loads and vacuum. Cast iron and concrete are the reverse.","marks":1,"source":{"kind":"past","set":6,"question":39,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q39 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-06-040","src":"PAST-06-040","text":"Why is an air gap left at the top of sewers?","options":[{"key":"a","text":"To meet the fluctuation of sewage inflow"},{"key":"b","text":"To maintain open channel flow condition"},{"key":"c","text":"To provide space over sewage for ventilation"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"Sewers are designed to run partly full (about \\(\\dfrac{2}{3}\\) to \\(\\dfrac{3}{4}\\) depth). The free space takes peak flows, keeps gravity (open-channel) flow and ventilates the sewer gases.","marks":1,"source":{"kind":"past","set":6,"question":40,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q40 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-06-041","src":"PAST-06-041","text":"1 TCU is equivalent to","options":[{"key":"a","text":"the colour produced by 1 g of platinum cobalt"},{"key":"b","text":"the colour produced by 1 mg of platinum cobalt"},{"key":"c","text":"the colour produced by 1 mg of platinum cobalt in 1 L of distilled water"},{"key":"d","text":"the colour produced by 1 mg of platinum cobalt in 1 mL of distilled water"}],"answer":"c","explanation":"One true colour unit (Hazen unit) is the colour produced by 1 mg/L of platinum (as chloroplatinate, with cobalt) in distilled water.","marks":1,"source":{"kind":"past","set":6,"question":41,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q41 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-06-058","src":"PAST-06-058","text":"In which of the following is scoping not required?","options":[{"key":"a","text":"BES"},{"key":"b","text":"IEE"},{"key":"c","text":"EIA"},{"key":"d","text":"TOR"}],"answer":"b","explanation":"Under Nepal's environment rules, scoping (with public notice) is a stage of EIA only. IEE proceeds on an approved ToR without scoping, and the newer BES needs neither. The source key's (c) contradicts its own note that scoping belongs to EIA.","marks":1,"source":{"kind":"past","set":6,"question":58,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q58 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-06-064","src":"PAST-06-064","text":"One litre of sewage, when allowed to settle for 30 minutes, gives a sludge volume of 27 cm<sup>3</sup>. If the dry weight of this sludge is 3.0 grams, then its sludge volume index will be","options":[{"key":"a","text":"9"},{"key":"b","text":"24"},{"key":"c","text":"30"},{"key":"d","text":"81"}],"answer":"a","explanation":"SVI is the settled volume in mL divided by the dry weight of solids in g: \\[\\text{SVI} = \\dfrac{27}{3.0} = 9\\ \\text{mL/g}\\]","marks":2,"source":{"kind":"past","set":6,"question":64,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q64 · 2 marks"},"topic":"ACiE0605"},{"id":"PAST-06-080","src":"PAST-06-080","text":"What is the formula for the overall efficiency of a two-stage HRTF?","options":[{"key":"a","text":"E1 + E2"},{"key":"b","text":"E1 + E2(1 − E1)"},{"key":"c","text":"1 − E1·E2"},{"key":"d","text":"(E1 + E2)/2"}],"answer":"b","explanation":"The second filter removes a fraction \\(E_2\\) of what the first leaves, \\(1 - E_1\\). The overall efficiency is therefore \\[E = E_1 + E_2(1 - E_1)\\]","marks":2,"source":{"kind":"past","set":6,"question":80,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q80 · 2 marks"},"topic":"ACiE0605"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-06-015","src":"PAST-06-015","text":"Which of the following types of water is usable by plants?","options":[{"key":"a","text":"Hygroscopic"},{"key":"b","text":"Chemical"},{"key":"c","text":"Gravity"},{"key":"d","text":"Capillary"}],"answer":"d","explanation":"Capillary water held between field capacity and the wilting point is the water available to plants. Gravity water drains away, and hygroscopic water is held too tightly to be used.","marks":1,"source":{"kind":"past","set":6,"question":15,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q15 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-06-034","src":"PAST-06-034","text":"Which is not a formation seen in an alluvial channel with sediment motion?","options":[{"key":"a","text":"Rippled"},{"key":"b","text":"Meandered"},{"key":"c","text":"Duned"},{"key":"d","text":"Antidunes"}],"answer":"b","explanation":"Ripples, dunes and antidunes are bed forms created by sediment motion. Meandering describes the channel's plan form, not a bed form.","marks":1,"source":{"kind":"past","set":6,"question":34,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q34 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-06-036","src":"PAST-06-036","text":"The discharge passing over an ogee weir is proportional to","options":[{"key":"a","text":"H"},{"key":"b","text":"√H"},{"key":"c","text":"H<sup>3/2</sup>"},{"key":"d","text":"H<sup>5/2</sup>"}],"answer":"c","explanation":"For weirs and spillways \\[Q = CLH^{3{/}2}\\] \\(H^{5{/}2}\\) applies to a triangular notch. The source key gives (b), although its own formula is \\(Q \\propto H^{3{/}2}\\).","marks":1,"source":{"kind":"past","set":6,"question":36,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q36 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-06-046","src":"PAST-06-046","text":"The method which uses dead furrows on cropped farms for drainage of excess irrigation or rain water is called","options":[{"key":"a","text":"Surface inlet"},{"key":"b","text":"Tile drainage"},{"key":"c","text":"Bedding"},{"key":"d","text":"French drain"}],"answer":"c","explanation":"In bedding, land is ploughed into raised beds separated by dead furrows, which collect and lead away excess surface water.","marks":1,"source":{"kind":"past","set":6,"question":46,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q46 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-06-047","src":"PAST-06-047","text":"What are cross drainage works carrying a canal over a natural drain called?","options":[{"key":"a","text":"Aqueduct and syphon aqueduct"},{"key":"b","text":"Canal syphon and super passage"},{"key":"c","text":"Aqueduct and super passage"},{"key":"d","text":"None of the above"}],"answer":"a","explanation":"When the canal passes over the drain it is an aqueduct (drain flows freely below) or a syphon aqueduct (drain flows under pressure). Super passages and canal syphons carry the drain over or under the canal.","marks":1,"source":{"kind":"past","set":6,"question":47,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q47 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-06-048","src":"PAST-06-048","text":"What can't you provide at a head regulator?","options":[{"key":"a","text":"Canal aqueduct"},{"key":"b","text":"Fish ladder"},{"key":"c","text":"Divide wall"},{"key":"d","text":"Under sluice"}],"answer":"a","explanation":"Fish ladders, divide walls and undersluices belong to the diversion headworks near the head regulator. An aqueduct is a cross-drainage work located along the canal, not at its head.","marks":1,"source":{"kind":"past","set":6,"question":48,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q48 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-06-062","src":"PAST-06-062","text":"If the D<sub>10</sub> of the particles is 2 mm and the discharge is 2 m<sup>3</sup>/s, then the longitudinal slope (by Lacey's theory) is","options":[{"key":"a","text":"1 in 520"},{"key":"b","text":"1 in 620"},{"key":"c","text":"1 in 720"},{"key":"d","text":"1 in 820"}],"answer":"d","explanation":"The silt factor is \\[f = 1.76\\sqrt{d} = 1.76\\sqrt{2} = 2.49\\] Lacey's slope is then \\[\\begin{aligned} S &amp;= \\dfrac{f^{5{/}3}}{3340\\,Q^{1{/}6}} \\\\ &amp;= \\dfrac{4.57}{3340 \\times 1.12} \\approx \\dfrac{1}{820} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":6,"question":62,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q62 · 2 marks"},"topic":"ACiE0702"},{"id":"PAST-06-065","src":"PAST-06-065","text":"The kor depth for rice is 190 mm and the kor period is 14 days. The outlet factor for this will be","options":[{"key":"a","text":"637 hectares/m<sup>3</sup>/sec"},{"key":"b","text":"837 hectares/m<sup>3</sup>/sec"},{"key":"c","text":"972 hectares/m<sup>3</sup>/sec"},{"key":"d","text":"1172 hectares/m<sup>3</sup>/sec"}],"answer":"a","explanation":"The duty is \\[\\begin{aligned} D &amp;= \\dfrac{8.64B}{\\Delta} = \\dfrac{8.64 \\times 14}{0.19} \\\\ &amp;\\approx 637 \\end{aligned}\\] hectares per cumec.","marks":2,"source":{"kind":"past","set":6,"question":65,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q65 · 2 marks"},"topic":"ACiE0701"},{"id":"PAST-06-076","src":"PAST-06-076","text":"A quantum of discharge with high enough magnitude and frequency to bring about changes to the river boundary and surrounding area is","options":[{"key":"a","text":"Maximum flood discharge"},{"key":"b","text":"Design discharge"},{"key":"c","text":"Median discharge"},{"key":"d","text":"Dominant discharge"}],"answer":"d","explanation":"The dominant (channel-forming) discharge is the steady flow that would produce the same channel shape as the actual varying regime. It is often close to the bankfull flow.","marks":2,"source":{"kind":"past","set":6,"question":76,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q76 · 2 marks"},"topic":"ACiE0704"}]},{"name":"Hydropower","questions":[{"id":"PAST-06-035","src":"PAST-06-035","text":"Which element of a hydroelectric power plant prevents the penstock from the water hammer phenomenon?","options":[{"key":"a","text":"Valves and gates"},{"key":"b","text":"Draft tubes"},{"key":"c","text":"Spillway"},{"key":"d","text":"Surge tank"}],"answer":"d","explanation":"The surge tank provides a free surface close to the turbines. It absorbs the pressure rise on sudden gate closure and so protects the penstock from water hammer.","marks":1,"source":{"kind":"past","set":6,"question":35,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q35 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-06-043","src":"PAST-06-043","text":"What is pondage?","options":[{"key":"a","text":"Holding back of water to form a pond"},{"key":"b","text":"Storing water for a long period of time"},{"key":"c","text":"Storing water for use in the peak period"},{"key":"d","text":"All of the above"}],"answer":"c","explanation":"Pondage is the small storage behind a run-of-river weir or in a forebay, used to meet daily peak-load fluctuations. Long-period storage is called storage (a reservoir), so (b) does not describe pondage. The source key gives (d).","marks":1,"source":{"kind":"past","set":6,"question":43,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q43 · 1 mark"},"topic":"ACiE0804"},{"id":"PAST-06-045","src":"PAST-06-045","text":"What is the purpose of providing free board?","options":[{"key":"a","text":"Stability against overturning and safety against gully erosion"},{"key":"b","text":"Stability against overturning and safety against frost crack"},{"key":"c","text":"u/s slope erosion control"},{"key":"d","text":"d/s slope erosion control"}],"answer":"b","explanation":"Freeboard keeps waves and floods from overtopping the dam, which could erode and destabilise it. In cold regions it also keeps the frost-cracked top zone above water. The key takes (b).","marks":1,"source":{"kind":"past","set":6,"question":45,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q45 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-06-050","src":"PAST-06-050","text":"For the BIERI settling basin, which of the following statements is false?","options":[{"key":"a","text":"It is continuous type"},{"key":"b","text":"It uses sensors"},{"key":"c","text":"It is used in Middle Marsyangdi"},{"key":"d","text":"Plant needs to be closed during flushing operation"}],"answer":"a","explanation":"The Bieri system flushes intermittently, not continuously. Sensors detect the deposited sediment and a travelling flushing unit removes it, so the key's false statement is (a).","marks":1,"source":{"kind":"past","set":6,"question":50,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q50 · 1 mark"},"topic":"ACiE0804"},{"id":"PAST-06-070","src":"PAST-06-070","text":"Which of the following is incorrect for a settling basin?","options":[{"key":"a","text":"1H:2V for horizontal direction"},{"key":"b","text":"1H:5V for vertical direction"},{"key":"c","text":"Used for removing silt"},{"key":"d","text":"Laminar flow"}],"answer":"b","explanation":"Settling basins remove silt by slowing the flow to a quiet, near-laminar state, with gradual inlet expansions. Following the source, a 1H:5V slope is not the recommended vertical expansion (the source quotes 1H:2V at the inlet and 1H:1V at the outlet), so (b) is the incorrect statement.","marks":2,"source":{"kind":"past","set":6,"question":70,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q70 · 2 marks"},"topic":"ACiE0804"}]},{"name":"Transportation","questions":[{"id":"PAST-06-005","src":"PAST-06-005","text":"Longitudinal channel-like depressions along the wheel paths of a flexible pavement are the failure known as","options":[{"key":"a","text":"Longitudinal cracking"},{"key":"b","text":"Rutting"},{"key":"c","text":"Shear failure"},{"key":"d","text":"Bleeding"}],"answer":"b","explanation":"Rutting is the channelised permanent depression in the wheel tracks, caused by densification or shear flow of the layers under repeated loads. (The paper's figure is not reproduced, so the question is reworded.)","marks":1,"source":{"kind":"past","set":6,"question":5,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q5 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-06-006","src":"PAST-06-006","text":"If the total lost time is 10 sec and the sum of the ratios of flow to saturation flow of the two directional traffic flows is 0.6, then the optimal cycle length is","options":[{"key":"a","text":"50"},{"key":"b","text":"60"},{"key":"c","text":"70"},{"key":"d","text":"80"}],"answer":"a","explanation":"Webster's optimum cycle is \\[\\begin{aligned} C_0 &amp;= \\dfrac{1.5L + 5}{1 - Y} \\\\ &amp;= \\dfrac{1.5 \\times 10 + 5}{1 - 0.6} = 50\\ \\text{s} \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":6,"question":6,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q6 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-06-009","src":"PAST-06-009","text":"Compaction depends on","options":[{"key":"a","text":"Number of repetitions"},{"key":"b","text":"Weight of roller"},{"key":"c","text":"Speed of roller"},{"key":"d","text":"All"}],"answer":"d","explanation":"The compactive effort delivered by a roller depends on its weight (contact pressure), the number of passes and its speed, along with the soil's moisture content.","marks":1,"source":{"kind":"past","set":6,"question":9,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q9 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-06-014","src":"PAST-06-014","text":"Relative compaction is","options":[{"key":"a","text":"γ<sub>dmax</sub>/γ<sub>d</sub>"},{"key":"b","text":"γ<sub>d</sub>/γ<sub>dmin</sub>"},{"key":"c","text":"γ<sub>d</sub>/γ<sub>dmax</sub>"},{"key":"d","text":"None"}],"answer":"c","explanation":"Relative compaction is the field dry density divided by the maximum dry density from the laboratory compaction test: \\[\\text{RC} = \\dfrac{\\gamma_d}{\\gamma_{d\\,max}} \\times 100\\] Specifications usually demand 95-98%.","marks":1,"source":{"kind":"past","set":6,"question":14,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q14 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-06-044","src":"PAST-06-044","text":"Extra widening is","options":[{"key":"a","text":"Psychological widening"},{"key":"b","text":"Mechanical widening"},{"key":"c","text":"Both a and b"},{"key":"d","text":"Curve"}],"answer":"c","explanation":"Extra widening on horizontal curves is mechanical plus psychological widening: \\[W_e = \\dfrac{nl^2}{2R} + \\dfrac{v}{9.5\\sqrt{R}}\\] the first term accounting for off-tracking.","marks":1,"source":{"kind":"past","set":6,"question":44,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q44 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-06-049","src":"PAST-06-049","text":"Which is not a fixed component (of a transportation system)?","options":[{"key":"a","text":"Airport"},{"key":"b","text":"Harbour"},{"key":"c","text":"Railroad track"},{"key":"d","text":"Railway locomotive"}],"answer":"d","explanation":"Airports, harbours and tracks are fixed facilities (infrastructure). Locomotives are vehicles, i.e. the moving component.","marks":1,"source":{"kind":"past","set":6,"question":49,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q49 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-06-054","src":"PAST-06-054","text":"The average of speeds observed at a particular place at different times is","options":[{"key":"a","text":"Point speed"},{"key":"b","text":"TMS"},{"key":"c","text":"SMS"},{"key":"d","text":"Average speed"}],"answer":"b","explanation":"Time mean speed is the average of the spot speeds of vehicles passing a fixed point over a period of time. Space mean speed averages the speeds of vehicles over a road length at an instant. The source key gives (c).","marks":1,"source":{"kind":"past","set":6,"question":54,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q54 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-06-057","src":"PAST-06-057","text":"What is the process dealing with vertical curves and gradients?","options":[{"key":"a","text":"Vertical control"},{"key":"b","text":"Vertical alignment"},{"key":"c","text":"Horizontal alignment"},{"key":"d","text":"Levelling"}],"answer":"b","explanation":"Vertical alignment is the road profile in the vertical plane: its gradients and the summit and valley curves joining them.","marks":1,"source":{"kind":"past","set":6,"question":57,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q57 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-06-068","src":"PAST-06-068","text":"What is the value of the (lane) distribution factor for a 4 lane road in Nepal?","options":[{"key":"a","text":"0.4 for single lane"},{"key":"b","text":"0.7 for both lane"},{"key":"c","text":"0.4 for both lane"},{"key":"d","text":"0.7 for single lane"}],"answer":"c","explanation":"For a four-lane single carriageway, the design traffic is taken as 40% of the total commercial vehicles in both directions (distribution factor 0.40). A two-lane road uses 0.75 and a single lane 1.0.","marks":2,"source":{"kind":"past","set":6,"question":68,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q68 · 2 marks"},"topic":"ACiE0905"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-06-004","src":"PAST-06-004","text":"Which line type is used to draw a centre line in engineering drawing?","options":[{"key":"a","text":"Continuous thick line"},{"key":"b","text":"Thin chain line (long dash and dot)"},{"key":"c","text":"Short dashed line"},{"key":"d","text":"Continuous thin wavy line"}],"answer":"b","explanation":"Centre lines and lines of symmetry are thin chain lines of alternate long dashes and dots. Visible edges are continuous thick lines, hidden edges are dashed and break lines are wavy. (The paper's figure is not reproduced, so the question is reworded.)","marks":1,"source":{"kind":"past","set":6,"question":4,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q4 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-06-051","src":"PAST-06-051","text":"Which method is mostly adopted by business enterprises?","options":[{"key":"a","text":"Payback"},{"key":"b","text":"Discounted payback"},{"key":"c","text":"IRR"},{"key":"d","text":"ARR"}],"answer":"c","explanation":"IRR accounts for the time value of money and gives a single percentage return that is easy to compare with the cost of capital, so business firms widely use it.","marks":1,"source":{"kind":"past","set":6,"question":51,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q51 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-06-052","src":"PAST-06-052","text":"Which is the first stage in project formulation?","options":[{"key":"a","text":"Planning"},{"key":"b","text":"Setting objectives"},{"key":"c","text":"Controlling"},{"key":"d","text":"Evaluating"}],"answer":"b","explanation":"Project formulation starts by defining objectives. Planning, implementation, control and evaluation follow.","marks":1,"source":{"kind":"past","set":6,"question":52,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q52 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-06-053","src":"PAST-06-053","text":"Salvage value is defined as","options":[{"key":"a","text":"the value of dismantled materials of a property at the end of its utility period"},{"key":"b","text":"the estimated value of a built-up property at the end of its useful life without being dismantled"},{"key":"c","text":"the value of the property shown in the account book in that particular year"},{"key":"d","text":"the present value of a property considering it to be replaced at current market rates"}],"answer":"b","explanation":"Salvage value is the value of the property at the end of its useful life without dismantling. Scrap value is the value of the dismantled materials, book value is the account-book figure and (d) describes replacement value.","marks":1,"source":{"kind":"past","set":6,"question":53,"marks":1,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q53 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-06-066","src":"PAST-06-066","text":"How many members are selected by NEC itself?","options":[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"3"},{"key":"d","text":"4"}],"answer":"b","explanation":"The Nepal Engineering Council Act lists two engineers nominated by the Council itself among its members. The others are nominated by the Government, come from NEA and academia, or serve as ex officio members.","marks":2,"source":{"kind":"past","set":6,"question":66,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q66 · 2 marks"},"topic":"AALL1006"},{"id":"PAST-06-069","src":"PAST-06-069","text":"In which of the following is the minimum value taken?","options":[{"key":"a","text":"Forward pass"},{"key":"b","text":"Backward pass"},{"key":"c","text":"Both"},{"key":"d","text":"None of the above"}],"answer":"b","explanation":"In the backward pass, the latest time of an event with several following activities is the minimum of their (LF − duration) values. The forward pass takes the maximum.","marks":2,"source":{"kind":"past","set":6,"question":69,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q69 · 2 marks"},"topic":"AALL1003"},{"id":"PAST-06-073","src":"PAST-06-073","text":"The Nepal Government handed over the fast-track project to the Nepal Army. After handing in, what type of contract was it?","options":[{"key":"a","text":"BOT"},{"key":"b","text":"BOOT"},{"key":"c","text":"Build and Design"},{"key":"d","text":"Build, Design, Procurement, Subcontracting and all works"}],"answer":"d","explanation":"The Kathmandu–Terai fast track was given to the Nepal Army to execute with government funds. The Army is responsible for design, procurement, subcontracting and construction (an EPC-type arrangement). No private party finances, owns or operates it, so it is not BOOT. The source key gives (b).","marks":2,"source":{"kind":"past","set":6,"question":73,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q73 · 2 marks"},"topic":"AALL1004"},{"id":"PAST-06-077","src":"PAST-06-077","text":"Which is not a professional engineering body?","options":[{"key":"a","text":"Nepal Engineering Association (NEA)"},{"key":"b","text":"Society of Electrical &amp; Electronics Association (SEEN)"},{"key":"c","text":"Society of Public Health Engineers Nepal (SOPHEN)"},{"key":"d","text":"Society of Consulting Architectural &amp; Engineering Firms (SCAEF)"}],"answer":"b","explanation":"NEA, SOPHEN and SCAEF are established engineering organisations in Nepal. The body named in (b) is not a recognised professional engineering body, which is the key's answer.","marks":2,"source":{"kind":"past","set":6,"question":77,"marks":2,"date":"2080 Mangsir 24","shift":"2nd shift","reference":"Past Paper Set 6, Q77 · 2 marks"},"topic":"AALL1006"}]}]};
